css:
.portstrat-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2b2420;
    background: linear-gradient(168deg, #faf6ee 0%, #f4ece0 55%, #efe6d6 100%);
    border-radius: 18px;
}

.portstrat-container * {
    box-sizing: border-box;
}

.portstrat-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #4a1320 0%, #6e1f30 48%, #8a2a3c 100%);
    color: #fbf3ef;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(74, 19, 32, 0.32);
    border-bottom: 4px solid #c9a14a;
}

.portstrat-header h1 {
    margin: 10px 0 12px;
    font-size: 2.45rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.portstrat-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #f0d9a0;
    background: rgba(201, 161, 74, 0.16);
    border: 1px solid rgba(201, 161, 74, 0.45);
    padding: 5px 14px;
    border-radius: 999px;
}

.portstrat-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.58;
    color: #f3ddd6;
}

.portstrat-families {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.portstrat-family {
    flex: 1;
    background: #fffdf9;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: 0 4px 14px rgba(74, 19, 32, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-left: 5px solid #8a2a3c;
}

.portstrat-family-open { border-left-color: #1f7a5a; }
.portstrat-family-incompany { border-left-color: #2f5e95; }
.portstrat-family-custom { border-left-color: #b5862b; }

.portstrat-family-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #4a1320;
}

.portstrat-family-open .portstrat-family-name { color: #1f7a5a; }
.portstrat-family-incompany .portstrat-family-name { color: #2f5e95; }
.portstrat-family-custom .portstrat-family-name { color: #9a6f1f; }

.portstrat-family-meta {
    font-size: 0.82rem;
    color: #6f6357;
    line-height: 1.42;
}

.portstrat-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a4b40;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.portstrat-period-counter #currentDay,
.portstrat-period-counter #maxPeriods {
    font-weight: 800;
    color: #8a2a3c;
}

.portstrat-round-name {
    background: rgba(138, 42, 60, 0.12);
    color: #8a2a3c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.portstrat-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a6f1f;
    background: rgba(201, 161, 74, 0.16);
    border: 1px solid rgba(201, 161, 74, 0.42);
    padding: 4px 12px;
    border-radius: 999px;
}

.portstrat-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.portstrat-status-card {
    background: #fffdf9;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(74, 19, 32, 0.08);
    border-top: 4px solid #8a2a3c;
}

.portstrat-card-contrib { border-top-color: #1f7a5a; }
.portstrat-card-capacity { border-top-color: #2f5e95; }
.portstrat-card-anchor { border-top-color: #b5862b; }
.portstrat-card-relevance { border-top-color: #7d4fb0; }

.portstrat-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a6c5e;
}

.portstrat-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #4a1320;
    font-variant-numeric: tabular-nums;
}

.portstrat-card-contrib .portstrat-value { color: #1f7a5a; }
.portstrat-card-capacity .portstrat-value { color: #2f5e95; }
.portstrat-card-anchor .portstrat-value { color: #9a6f1f; }
.portstrat-card-relevance .portstrat-value { color: #7d4fb0; }

.portstrat-sublabel {
    font-size: 0.76rem;
    color: #837464;
    line-height: 1.36;
}

/* Contribution: green when target met, red when far below. */
.portstrat-card-contrib.portstrat-contrib-win { border-top-color: #1f7a5a; }
.portstrat-card-contrib.portstrat-contrib-win .portstrat-value { color: #1f7a5a; }
.portstrat-card-contrib.portstrat-contrib-miss { border-top-color: #c0392b; }
.portstrat-card-contrib.portstrat-contrib-miss .portstrat-value { color: #c0392b; }

/* Capacity: red over the ceiling. */
.portstrat-card-capacity.portstrat-cap-over { border-top-color: #c0392b; }
.portstrat-card-capacity.portstrat-cap-over .portstrat-value { color: #c0392b; }
.portstrat-card-capacity.portstrat-cap-warn { border-top-color: #c98a1a; }
.portstrat-card-capacity.portstrat-cap-warn .portstrat-value { color: #c98a1a; }

/* Anchor: green held, red conceded/lost. */
.portstrat-card-anchor.portstrat-anchor-held { border-top-color: #1f7a5a; }
.portstrat-card-anchor.portstrat-anchor-held .portstrat-value { color: #1f7a5a; }
.portstrat-card-anchor.portstrat-anchor-lost { border-top-color: #c0392b; }
.portstrat-card-anchor.portstrat-anchor-lost .portstrat-value { color: #c0392b; }

.portstrat-gap-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fffdf9;
    border: 1px solid #e6dcc9;
    color: #5a4b40;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.portstrat-gap-bar #gapDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.2px;
    color: #c0392b;
    font-weight: 800;
}

.portstrat-gap-bar.portstrat-gap-met #gapDisplay { color: #1f7a5a; }
.portstrat-gap-bar.portstrat-gap-close #gapDisplay { color: #c98a1a; }

.portstrat-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf9;
    border-left: 5px solid #c9a14a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 19, 32, 0.07);
}

.portstrat-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.portstrat-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #4a1320;
    margin-bottom: 6px;
}

.portstrat-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #4a3f35;
}

.portstrat-briefing-text strong { color: #8a2a3c; }
.portstrat-briefing-text em { color: #9a6f1f; font-style: italic; }

.portstrat-controls {
    background: #fffdf9;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 19, 32, 0.07);
}

.portstrat-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #4a1320;
    border-bottom: 2px solid #efe3cf;
    padding-bottom: 8px;
}

.portstrat-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a2f26;
    margin: 14px 0 6px;
}

.portstrat-container select,
.portstrat-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c9b0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #2b2420;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.portstrat-container select:focus,
.portstrat-container input[type="number"]:focus {
    outline: none;
    border-color: #8a2a3c;
    box-shadow: 0 0 0 3px rgba(138, 42, 60, 0.15);
}

.portstrat-container select option {
    background-color: #ffffff;
    color: #2b2420;
}

.portstrat-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #8a2a3c;
}

.portstrat-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5a4b40;
    margin-top: 4px;
}

.portstrat-range-readout span:nth-child(2) {
    color: #8a2a3c;
    font-weight: 800;
}

.portstrat-hint {
    font-size: 0.8rem;
    color: #837464;
    margin-top: 6px;
    line-height: 1.42;
    font-style: italic;
}

.portstrat-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.portstrat-container .btn-primary {
    background: linear-gradient(135deg, #6e1f30 0%, #8a2a3c 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(110, 31, 48, 0.32);
}

.portstrat-container .btn-primary:hover {
    filter: brightness(1.08);
}

.portstrat-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #d8c9b0;
    color: #6f6357;
    background: transparent;
}

.portstrat-coach {
    background: linear-gradient(160deg, #2a2e3e 0%, #353a50 100%);
    color: #ece7df;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(42, 46, 62, 0.26);
    border-left: 4px solid #c9a14a;
}

.portstrat-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0d9a0;
    margin-bottom: 8px;
}

.portstrat-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.portstrat-coach-body strong { color: #e8b9c2; }
.portstrat-coach-body em { color: #f0d9a0; font-style: italic; }

.portstrat-history,
.portstrat-chart {
    background: #fffdf9;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(74, 19, 32, 0.07);
}

.portstrat-history h3,
.portstrat-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #4a1320;
}

.portstrat-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a3f35;
}

.portstrat-container table#usfHistoryTable th {
    background: #f5ecdc;
    color: #8a2a3c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e6d8be;
}

.portstrat-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e8da;
    color: #4a3f35;
}

.portstrat-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf4e9;
}

.portstrat-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .portstrat-container {
        padding: 14px;
    }
    .portstrat-header h1 {
        font-size: 1.7rem;
    }
    .portstrat-families {
        flex-direction: column;
    }
    .portstrat-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .portstrat-value {
        font-size: 2rem;
    }
    .portstrat-clock {
        margin-left: 0;
    }
    .portstrat-period-counter {
        font-size: 0.88rem;
    }
    .portstrat-gap-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .portstrat-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / board-debrief screen (portstrat) ---- */
.portstrat-cm { padding: 8px 4px 4px; color: #efe7dd; }
.portstrat-cm-head { text-align: center; margin-bottom: 18px; }
.portstrat-cm-score { font-size: 3.4rem; font-weight: 800; line-height: 1; color: #c9a25f; }
.portstrat-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #a58f70; }
.portstrat-cm-verdict { font-size: 1.2rem; font-weight: 700; margin-top: 8px; color: #f6efe6; }
.portstrat-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.76rem; font-weight: 700; vertical-align: middle; }
.portstrat-cm-yes { background: rgba(201,162,95,0.16); color: #c9a25f; border: 1px solid rgba(201,162,95,0.5); }
.portstrat-cm-no { background: rgba(180,90,70,0.13); color: #d18a72; border: 1px solid rgba(180,90,70,0.45); }
.portstrat-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 14px 0; }
.portstrat-cm-metric { flex: 1 1 110px; min-width: 96px; background: rgba(201,162,95,0.08); border: 1px solid rgba(201,162,95,0.22); border-radius: 10px; padding: 12px 8px; text-align: center; }
.portstrat-cm-mv { display: block; font-size: 1.5rem; font-weight: 800; color: #c9a25f; }
.portstrat-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #b6a488; text-transform: uppercase; letter-spacing: 0.04em; }
.portstrat-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin: 4px 0 16px; }
.portstrat-cm-chip { font-size: 0.78rem; font-weight: 600; padding: 4px 12px; border-radius: 999px; border: 1px solid transparent; }
.portstrat-cm-chip-on { background: rgba(201,162,95,0.14); color: #ddb877; border-color: rgba(201,162,95,0.4); }
.portstrat-cm-chip-off { background: rgba(180,164,136,0.08); color: #9a8c76; border-color: rgba(180,164,136,0.22); }
.portstrat-cm-debrief-title { font-weight: 700; margin: 10px 0 6px; color: #f6efe6; }
.portstrat-cm-insights { margin: 0; padding-left: 20px; }
.portstrat-cm-insights li { margin-bottom: 9px; line-height: 1.55; font-size: 0.92rem; color: #d8ccbc; }

