        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.contribHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `Q` + i));
            // Contribution is ~2–2.7 EUR M — scale ×40 to share the 0–140 axis with % and index.
            const contribScaled = ds.contribHistory.map((v) => Math.round(v * 40));
            return {
                portfolioChart: {
                    labels: labels,
                    datasets: [
                        { data: contribScaled },
                        { data: ds.utilHistory },
                        { data: ds.relevanceHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const contrib = Math.round(ds.contrib * 100) / 100;
            const util = Math.round(ds.util);
            const relevance = Math.round(ds.relevance);
            const withinCeiling = util <= 100 && !ds.overCapacity;
            const contribScore = Math.max(0, Math.min(100, ((contrib - 1.8) / (this.TARGET_CONTRIB - 1.8)) * 80));
            const capScore = withinCeiling ? 100 : Math.max(0, 100 - (util - 100) * 8);
            return Math.round(contribScore * 0.5 + capScore * 0.22 + relevance * 0.28);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        _gradeLabel(perf) {
            const map = {
                "Unit Folded": `grade_folded`,
                "Portfolio Rebalanced": `grade_rebalanced`,
                "Spread Too Thin": `grade_scattered`,
                "Capacity Blown": `grade_overcap`,
                "Anchor Lost": `grade_anchorlost`,
                "Margin Surrendered": `grade_concede`,
                "Funnel Severed": `grade_funnel`,
                "Close, Not There": `grade_close`,
                "Held the Line": `grade_held`
            };
            const key = map[perf];
            return key ? this._cl(key, perf) : perf;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const contrib = Math.round(ds.contrib * 100) / 100;
            const util = Math.round(ds.util);
            const relevance = Math.round(ds.relevance);

            const targetMet = contrib >= this.TARGET_CONTRIB;
            const withinCeiling = util <= 100 && !ds.overCapacity;
            const anchorDefended = (ds.anchorState === `held`);
            const focused = !ds.scattered && relevance >= 60;
            const yieldLed = !ds.revenueRanked;
            const funnelIntact = !ds.cutFunnel;

            // Composite: contribution against target dominates, then capacity, relevance.
            const contribScore = Math.max(0, Math.min(100,
                ((contrib - 1.8) / (this.TARGET_CONTRIB - 1.8)) * 80
            ));
            const capScore = withinCeiling ? 100 : Math.max(0, 100 - (util - 100) * 8);
            const composite = Math.round(contribScore * 0.5 + capScore * 0.22 + relevance * 0.28);

            // Top verdict is GATED by every sticky flag AND the hard target.
            let performance = `Unit Folded`;
            if (targetMet && withinCeiling && anchorDefended && focused && yieldLed && funnelIntact && composite >= 78) {
                performance = `Portfolio Rebalanced`;
            } else if (ds.scattered) {
                // Headline error #2 is checked before generic over-capacity so the
                // four-sector scatter surfaces its own diagnostic verdict.
                performance = `Spread Too Thin`;
            } else if (ds.overCapacity) {
                performance = `Capacity Blown`;
            } else if (ds.anchorState === `lost`) {
                performance = `Anchor Lost`;
            } else if (ds.concededAnchor) {
                performance = `Margin Surrendered`;
            } else if (ds.cutFunnel) {
                // Headline error #5: killing the discovery funnel cannot reach the top band,
                // even when contribution looks healthy this year.
                performance = `Funnel Severed`;
            } else if (contrib >= 2.45) {
                performance = `Close, Not There`;
            } else if (contrib >= this.START_CONTRIB) {
                performance = `Held the Line`;
            }

            const insights = [];
            if (performance === `Portfolio Rebalanced`) insights.push(window.mySimulation.t(`insight_rebalanced`));
            else if (ds.scattered) insights.push(window.mySimulation.t(`insight_scatter`));
            else if (ds.overCapacity) insights.push(window.mySimulation.t(`insight_overcapacity`));
            else if (ds.anchorState === `lost`) insights.push(window.mySimulation.t(`insight_anchorlost`));
            else if (ds.concededAnchor) insights.push(window.mySimulation.t(`insight_concede`));
            else if (ds.cutFunnel) insights.push(window.mySimulation.t(`insight_funnel`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.revenueRanked) insights.push(window.mySimulation.t(`insight_revenue`));
            if (!targetMet && !ds.overCapacity && !ds.scattered && ds.anchorState !== `lost`) insights.push(window.mySimulation.t(`insight_gap`));
            if (targetMet && util >= 99 && util <= 100) insights.push(window.mySimulation.t(`insight_tight`));

            return {
                contrib: contrib,
                util: util,
                relevance: relevance,
                gap: Math.round((this.TARGET_CONTRIB - contrib) * 100) / 100,
                targetMet: targetMet,
                withinCeiling: withinCeiling,
                anchorDefended: anchorDefended,
                focused: focused,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                met: (targetMet && withinCeiling && anchorDefended && focused && yieldLed && funnelIntact && composite >= 78),
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function (k) { return window.mySimulation.t(k); }
                : function (k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const verdict = s.performanceLabel || s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="portstrat-cm-badge portstrat-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="portstrat-cm-badge portstrat-cm-no">` + T(`cm_notmet`) + `</span>`;
            const chip = function (ok, key) {
                return `<span class="portstrat-cm-chip ` + (ok ? `portstrat-cm-chip-on` : `portstrat-cm-chip-off`) + `">`
                    + (ok ? `✓ ` : `· `) + T(key) + `</span>`;
            };
            const chips = chip(!!s.targetMet, `cm_b_target`) + chip(!!s.withinCeiling, `cm_b_ceiling`)
                + chip(!!s.anchorDefended, `cm_b_anchor`) + chip(!!s.focused, `cm_b_focused`);
            const md = function (val, key) {
                return `<div class="portstrat-cm-metric"><span class="portstrat-cm-mv">` + val
                    + `</span><span class="portstrat-cm-ml">` + T(key) + `</span></div>`;
            };
            const metrics = md(self._fmtContrib(s.contrib || 0), `cm_m_contrib`)
                + md(Math.round(s.util || 0) + `%`, `cm_m_util`)
                + md(Math.round(s.relevance || 0), `cm_m_relevance`)
                + md((Math.round((s.gap || 0) * 100) / 100), `cm_m_gap`);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function (t) { return `<li>` + t + `</li>`; }).join(``);
            return `<div class="portstrat-cm">`
                + `<div class="portstrat-cm-head">`
                +   `<div class="portstrat-cm-score">` + score + `<span class="portstrat-cm-score-max">/100</span></div>`
                +   `<div class="portstrat-cm-verdict">` + verdict + ` ` + badge + `</div>`
                + `</div>`
                + `<div class="portstrat-cm-metrics">` + metrics + `</div>`
                + `<div class="portstrat-cm-chips">` + chips + `</div>`
                + `<div class="portstrat-cm-debrief-title">` + T(`cm_debrief`) + `</div>`
                + `<ul class="portstrat-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overCapacity) return window.mySimulation.t(`hint_overcapacity`);
            if (ds.anchorState === `lost`) return window.mySimulation.t(`hint_anchorlost`);
            if (ds.concededAnchor) return window.mySimulation.t(`hint_concede`);
            if (ds.scattered) return window.mySimulation.t(`hint_scatter`);
            if (ds.revenueRanked && state.currentPeriod >= 2) return window.mySimulation.t(`hint_revenue`);
            if (ds.contrib < this.TARGET_CONTRIB && state.currentPeriod >= 3) return window.mySimulation.t(`hint_gap`);
            if (ds.contrib >= this.TARGET_CONTRIB && ds.util <= 100 && ds.anchorState === `held`) return window.mySimulation.t(`hint_strong`);
            return null;
        }

